-- I. upgrade_20261118_flow_config_data.sql —— 流程配置数据同步(11-18,含请假表单定义)
-- ============================================================
-- =============================================================
-- 流程配置数据同步脚本（标准仓 → 分支仓）
-- 日期：2026-11-18
-- 同步内容（2026-11-15~18 新建或更新的流程配置）：
--   1) 流程表单：请假(2)、用印申请单(13)、用印(17)、采购(18)、公车(19)、
--      费用报销(21, 含 ext_json 交互规则)、出差申请(22)、外出(23)、打卡补卡(24)
--   2) 流程模型：出差/外出/打卡补卡/费用报销/公车使用申请 及其编辑源
--   3) 流程部署与定义：busUseApply / expenseReimburse:v2 / travelApply / outingApply / makeupApply
--   4) 节点表单配置：busUseApply、expenseReimburse
--   5) 流程定义备注：flow_procdef_ext (busUseApply)
--   6) 动态数据表：报销(flow_data_expense_reimburse(+_dt1))、外出、补卡、出差
--   7) 用印数据表补列 seal_name
-- 说明：可重复执行（先按主键清理再插入，ID 与标准仓保持一致）；
--       执行命令必须带 --default-character-set=utf8mb4
-- =============================================================
SET NAMES utf8mb4;

