-- ---------- 2. 动态数据表（表单对应物理表，幂等建表） ----------
CREATE TABLE IF NOT EXISTS `flow_data_expense_reimburse` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL COMMENT '标题',
  `processNo` varchar(64) DEFAULT NULL COMMENT '流程编号',
  `urgency` varchar(20) DEFAULT NULL COMMENT '紧急程度',
  `signOpinion` varchar(4000) DEFAULT NULL COMMENT '签字意见',
  `printCount` int DEFAULT NULL COMMENT '打印次数',
  `procStatus` varchar(20) DEFAULT NULL COMMENT '流程状态',
  `applicant` varchar(1000) DEFAULT NULL COMMENT '申请人',
  `apply_dept` varchar(1000) DEFAULT NULL COMMENT '所属部门',
  `post_name` varchar(1000) DEFAULT NULL COMMENT '岗位',
  `reimburse_date` date DEFAULT NULL COMMENT '报销日期',
  `project_name` varchar(1000) DEFAULT NULL COMMENT '关联项目',
  `need_loan_offset` varchar(100) DEFAULT NULL COMMENT '是否冲抵借款',
  `loan_amount` decimal(18,2) DEFAULT NULL COMMENT '借款金额（元）',
  `offset_amount` decimal(18,2) DEFAULT NULL COMMENT '本次冲抵金额（元）',
  `total_amount` decimal(18,2) DEFAULT NULL COMMENT '合计金额（小写，元）',
  `total_amount_cn` varchar(200) DEFAULT NULL COMMENT '合计金额（大写）',
  `attachment` varchar(2000) DEFAULT NULL COMMENT '附件（发票影像）',
  `process_instance_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`(191)),
  KEY `idx_urgency` (`urgency`),
  KEY `idx_process_no` (`processNo`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='费用报销流程数据';

CREATE TABLE IF NOT EXISTS `flow_data_expense_reimburse_dt1` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `mainid` bigint NOT NULL COMMENT '主表主键ID',
  `expense_type` varchar(100) DEFAULT NULL COMMENT '费用类型',
  `expense_item` varchar(200) DEFAULT NULL COMMENT '费用项目',
  `occur_date` date DEFAULT NULL COMMENT '发生日期',
  `amount` decimal(18,2) DEFAULT NULL COMMENT '金额（元）',
  `memo` varchar(500) DEFAULT NULL COMMENT '说明',
  `process_instance_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_mainid` (`mainid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='费用报销明细表1';

CREATE TABLE IF NOT EXISTS `flow_data_outing_apply` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL COMMENT '标题',
  `processNo` varchar(64) DEFAULT NULL COMMENT '流程编号',
  `urgency` varchar(20) DEFAULT NULL COMMENT '紧急程度',
  `signOpinion` varchar(4000) DEFAULT NULL COMMENT '签字意见',
  `printCount` int DEFAULT NULL COMMENT '打印次数',
  `procStatus` varchar(20) DEFAULT NULL COMMENT '流程状态',
  `applicant` varchar(1000) DEFAULT NULL COMMENT '申请人',
  `apply_dept` varchar(1000) DEFAULT NULL COMMENT '所属部门',
  `post_name` varchar(1000) DEFAULT NULL COMMENT '岗位',
  `apply_date` date DEFAULT NULL COMMENT '申请日期',
  `outing_reason` varchar(1000) DEFAULT NULL COMMENT '外出事由',
  `outing_place` varchar(200) DEFAULT NULL COMMENT '外出地点',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `outing_hours` decimal(18,2) DEFAULT NULL COMMENT '外出时长（小时）',
  `attachment` varchar(2000) DEFAULT NULL COMMENT '附件',
  `process_instance_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`(191)),
  KEY `idx_urgency` (`urgency`),
  KEY `idx_process_no` (`processNo`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='外出申请流程数据';

CREATE TABLE IF NOT EXISTS `flow_data_makeup_apply` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL COMMENT '标题',
  `processNo` varchar(64) DEFAULT NULL COMMENT '流程编号',
