  `makeup_date` date DEFAULT NULL COMMENT '补卡日期',
  `shift_type` varchar(100) DEFAULT NULL COMMENT '补卡班次',
  `makeup_time` datetime DEFAULT NULL COMMENT '补卡时间',
  `makeup_reason` varchar(500) DEFAULT NULL COMMENT '补卡事由',
