\":\"browse\",\"browseType\":\"dept\",\"browseMultiple\":false,\"dtype\":\"text\",\"length\":1000,\"scale\":2,\"table\":\"main\",\"order\":8,\"required\":true,\"defaultMode\":\"currentDept\",\"placeholder\":\"系统自动带出当前部门\"},{\"field\":\"phone\",\"label\":\"联系电话\",\"form\":\"text\",\"dtype\":\"text\",\"length\":20,\"scale\":2,\"table\":\"main\",\"order\":9,\"required\":true,\"placeholder\":\"用车期间可联系到本人\"},{\"field\":\"use_reason\",\"label\":\"用车事由\",\"form\":\"textarea\",\"dtype\":\"text\",\"length\":2000,\"scale\":2,\"table\":\"main\",\"order\":10,\"required\":true,\"rows\":4,\"placeholder\":\"说明公务事由及随行人员\"},{\"field\":\"use_type\",\"label\":\"用车类型\",\"form\":\"select\",\"dtype\":\"text\",\"length\":40,\"scale\":2,\"table\":\"main\",\"order\":11,\"required\":true,\"selectOptions\":[{\"label\":\"市内公务\",\"value\":\"市内公务\"},{\"label\":\"市外公务\",\"value\":\"市外公务\"},{\"label\":\"客户接待\",\"value\":\"客户接待\"},{\"label\":\"物资运送\",\"value\":\"物资运送\"},{\"label\":\"其他\",\"value\":\"其他\"}]},{\"field\":\"depart_time\",\"label\":\"出发时间\",\"form\":\"datetime\",\"dtype\":\"datetime\",\"length\":500,\"scale\":2,\"table\":\"main\",\"order\":12,\"required\":true,\"placeholder\":\"不得早于提交时间\"},{\"field\":\"return_time\",\"label\":\"返回时间\",\"form\":\"datetime\",\"dtype\":\"datetime\",\"length\":500,\"scale\":2,\"table\":\"main\",\"order\":13,\"required\":true,\"placeholder\":\"须晚于出发时间\"},{\"field\":\"use_days\",\"label\":\"用车天数\",\"form\":\"number\",\"dtype\":\"float\",\"length\":500,\"scale\":1,\"table\":\"main\",\"order\":14,\"required\":false,\"placeholder\":\"按起止时间自动计算\"},{\"field\":\"passenger_count\",\"label\":\"乘车人数\",\"form\":\"number\",\"dtype\":\"int\",\"length\":11,\"scale\":2,\"table\":\"main\",\"order\":15,\"required\":true,\"placeholder\":\"含驾驶员，超过7人提示改用其他方式\"},{\"field\":\"destination\",\"label\":\"目的地/路线\",\"form\":\"text\",\"dtype\":\"text\",\"length\":500,\"scale\":2,\"table\":\"main\",\"order\":16,\"required\":true,\"placeholder\":\"市外用车须写明往返城市与途经地\"},{\"field\":\"need_dri