-- ============================================================
-- K. business_map_menu.sql —— 业务地图菜单
-- ============================================================
-- =============================================
-- 业务全景图 - 菜单权限 SQL
-- 变更内容：新增「业务全景图」一级菜单（C 类型）
-- 页面文件：ruoyi-ui/src/views/business-map/index.vue
-- 说明：可重复执行，已存在则跳过插入
-- =============================================

-- 0. 清理历史重跑遗留的重复「业务全景图」顶级菜单（保留最老一条）
SET @keepMap := (SELECT MIN(menu_id) FROM sys_menu
                 WHERE path IN ('/business-map', 'business-map') AND parent_id = 0
                   AND menu_type IN ('C', 'M'));
DELETE rm FROM sys_role_menu rm
  JOIN sys_menu m ON m.menu_id = rm.menu_id
 WHERE m.path IN ('/business-map', 'business-map') AND m.parent_id = 0
   AND m.menu_type IN ('C', 'M') AND m.menu_id <> @keepMap;
DELETE c FROM sys_menu c
  JOIN sys_menu p ON c.parent_id = p.menu_id
 WHERE p.path IN ('/business-map', 'business-map') AND p.parent_id = 0
   AND p.menu_type IN ('C', 'M') AND p.menu_id <> @keepMap;
DELETE m FROM sys_menu m
 WHERE m.path IN ('/business-map', 'business-map') AND m.parent_id = 0
   AND m.menu_type IN ('C', 'M') AND m.menu_id <> @keepMap;
-- 兜底：清理历史菜单删除遗留的角色授权孤儿
DELETE rm FROM sys_role_menu rm LEFT JOIN sys_menu m ON m.menu_id = rm.menu_id
 WHERE m.menu_id IS NULL;

-- 1. 新增业务全景图菜单（一级菜单；C/M 任一形态已存在则跳过）
INSERT INTO sys_menu (menu_name, parent_id, order_num, path, component, query, route_name,
                      is_frame, is_cache, menu_type, visible, status, perms, icon,
                      create_by, create_time, remark)
SELECT '业务全景图', 0, 1, '/business-map', 'business-map/index', '', 'BusinessMap',
       1, 0, 'C', '0', '0', 'business:map:view', 'guide',
       'admin', sysdate(), '新手引导：业务模块全景与数据流向'
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM sys_menu
    WHERE path IN ('/business-map', 'business-map') AND parent_id = 0
      AND menu_type IN ('C', 'M')
);

-- 2. 取得菜单 ID（兼容 C / M 两种形态）
SET @mapMenuId = (SELECT menu_id FROM sys_menu
                  WHERE path IN ('/business-map', 'business-map') AND parent_id = 0
                    AND menu_type IN ('C', 'M') LIMIT 1);

-- 3. 授权给现有全部有效角色（可按实际需要删减）
INSERT INTO sys_role_menu (role_id, menu_id)
SELECT r.role_id, @mapMenuId
FROM sys_role r
WHERE r.del_flag = '0'
  AND NOT EXISTS (
      SELECT 1 FROM sys_role_menu rm WHERE rm.role_id = r.role_id AND rm.menu_id = @mapMenuId
  );

-- 4. 校验
SELECT m.menu_id, m.menu_name, m.path, m.component, m.perms,
       (SELECT COUNT(1) FROM sys_role_menu rm WHERE rm.menu_id = m.menu_id) AS granted_roles
FROM sys_menu m
WHERE m.path = '/business-map';


-- ============================================================
-- L. fix_business_map_route.sql —— 业务地图路由修复
-- ============================================================
-- ---------------------------------------------------------------------------
-- 修复「业务全景图」菜单点击 404
--
-- 原因：
--   sys_menu 中业务全景图原为「一级 C 类型菜单」（parent_id = 0）。
--   RuoYi 后端 buildMenus 对一级 C 菜单会包一层 path = "/" 的 Layout 父路由，
--   而系统里已有另一个一级 C 菜单（消息）同样生成 path = "/" 的父路由。
--   前端 addRoute 后存在两条相同 path 的顶级记录，Vue Router 匹配时后插入的
--   「消息」记录优先，其 children 里没有 /business-map，最终落到 catch-all → 404。
--
-- 修复：
--   改为 RuoYi 标准结构「M 目录（业务全景图） + C 子菜单（index）」，
--   父路由 path 唯一（/business-map），不再产生 path = "/" 的重复记录。
--   侧边栏只有一个可见子项时会自动折叠为单条菜单，点击直达 /business-map/index。
--
-- 执行：mysql -uroot -p ry-vue < sql/fix_business_map_route.sql （幂等，可重复执行）
-- ---------------------------------------------------------------------------

-- 1. 原一级 C 菜单 → M 目录（component 用 Layout，perms 留给子菜单）
--    注意：RuoYi 对「一级 M 目录」会自动补前导 '/'，所以 path 必须写 business-map（不能带 '/'），
--    否则 getRouterPath 会拼成 '//business-map'，前端路由再次 404。
UPDATE sys_menu
   SET menu_type = 'M',
       component = 'Layout',
       perms     = '',
       path      = 'business-map',
       parent_id = 0,
       visible   = '0',
       status    = '0',
       update_by = 'admin',
       update_time = NOW()
 WHERE menu_type IN ('C', 'M') AND (path = '/business-map' OR path = 'business-map') AND parent_id = 0;

-- 2. 补齐子菜单（指向真实页面组件）
SET @mapMenuId = (SELECT menu_id FROM sys_menu WHERE path = 'business-map' AND menu_type = 'M' LIMIT 1);

--    父目录 route_name 置空：避免父子路由 name 同名（vue-router 会告警且 keep-alive 失效）
UPDATE sys_menu SET route_name = '' WHERE menu_id = @mapMenuId;

INSERT INTO sys_menu (menu_name, parent_id, order_num, path, component, query, route_name,
                      is_frame, is_cache, menu_type, visible, status, perms, icon,
                      create_by, create_time, remark)
SELECT '业务全景图', @mapMenuId, 1, 'index', 'business-map/index', '', 'BusinessMap',
       1, 0, 'C', '0', '0', 'business:map:view', 'guide',
       'admin', sysdate(), '新手引导：业务模块全景与数据流向'
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM sys_menu WHERE parent_id = @mapMenuId AND path = 'index'
);

-- 3. 子菜单授权（沿用父菜单已有的角色范围）
INSERT INTO sys_role_menu (role_id, menu_id)
SELECT rm.role_id, c.menu_id
FROM sys_role_menu rm
JOIN sys_menu c ON c.parent_id = rm.menu_id AND c.path = 'index' AND c.menu_type = 'C'
WHERE rm.menu_id = @mapMenuId
  AND NOT EXISTS (
      SELECT 1 FROM sys_role_menu x WHERE x.role_id = rm.role_id AND x.menu_id = c.menu_id
  );

-- 4. 新手任务里的入口路径同步为子菜单路径（原 /business-map 变成目录，直接 push 会白屏）
UPDATE sys_role_onboard_task
   SET menu_path = '/business-map/index',
       update_time = NOW()
 WHERE menu_path = '/business-map';

-- 5. 校验：应看到 1 条 M（path=business-map）+ 1 条 C（path=index）
SELECT m.menu_id, m.menu_name, m.parent_id, m.path, m.component, m.menu_type, m.perms,
       (SELECT COUNT(1) FROM sys_role_menu rm WHERE rm.menu_id = m.menu_id) AS granted_roles
  FROM sys_menu m
 WHERE m.path = 'business-map' OR m.parent_id = @mapMenuId
 ORDER BY m.parent_id, m.order_num;


-- ============================================================
-- M. module_switch_add_oa.sql —— 模块开关增加综合办公OA
-- ============================================================
-- ---------------------------------------------------------------------------
-- 模块开关补齐与路由修正
--
-- 1) 补登「综合办公(oa)」模块：该模块有顶级菜单但 sys_module 无登记，
--    导致后台「模块开关」管不到它，工作台「自定义常用功能」里永远显示。
-- 2) 修正「决策支持」菜单 path：原值 '/bi'（带前导斜杠），
--    RuoYi 对一级 M 目录会自动补 '/'，最终路由为 '//bi'，点击 404。
--
-- 执行：mysql -uroot -p ry-vue < sql/module_switch_add_oa.sql （幂等，可重复执行）
-- ---------------------------------------------------------------------------

-- 1. 修正决策支持（一级 M 目录 path 不能带前导斜杠）
UPDATE sys_menu SET path = 'bi', update_time = NOW()
 WHERE menu_id = 9062263 AND path = '/bi';

-- 2. 补登综合办公模块
INSERT INTO sys_module (module_name, module_key, root_menu_id, status, is_core, order_num, create_by, create_time, remark)
SELECT '综合办公', 'oa', 9064000, '0', '0', 20, 'admin', NOW(), '综合办公模块（印章/车辆/司机/保险），级联菜单 9064000 及其子菜单'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM sys_module WHERE module_key = 'oa');

-- 3. 校验：所有顶级业务目录都应能在 sys_module 找到对应开关
SELECT m.menu_id, m.menu_name, m.path,
       (SELECT sm.module_key FROM sys_module sm WHERE sm.root_menu_id = m.menu_id) AS bound_key
  FROM sys_menu m
 WHERE m.parent_id = 0 AND m.menu_type = 'M' AND m.status = '0'
 ORDER BY m.order_num;


-- ============================================================
-- N. home_role_kpi.sql —— 角色首页KPI配置(建sys_role_kpi表,先于默认5卡执行)
-- ============================================================
-- ---------------------------------------------------------------------------
-- 首页岗位化 KPI 配置（第二阶段 P0：KPI 按岗位取 4 张卡）
--
-- 设计取舍：
-- 1. 指标编码（metric_key）在后端注册，配置表只存"哪个岗位看哪几个指标"，
--    避免把取数 SQL 写进数据库（不可版本管理、易被误改）；
-- 2. 岗位用 role_key 关联 sys_role，和新人清单（sys_role_onboard_task）保持同一套岗位口径；
-- 3. 未配置岗位的角色（如 admin、普通员工）不返回 roleKpis，前端自动回退到原"按模块"卡片，
--    保证灰度上线期间老用户界面不变。
--
-- 执行：mysql -uroot -p ry-vue < sql/home_role_kpi.sql （幂等，可重复执行）
-- ---------------------------------------------------------------------------

-- 1. 岗位 KPI 配置表
CREATE TABLE IF NOT EXISTS sys_role_kpi (
  id            bigint(20)   NOT NULL AUTO_INCREMENT COMMENT '主键',
  role_key      varchar(64)  NOT NULL                COMMENT '岗位角色标识（sys_role.role_key）',
  seq           int(4)       NOT NULL DEFAULT '1'    COMMENT '展示顺序',
  metric_key    varchar(64)  NOT NULL                COMMENT '指标编码（后端指标注册表）',
  title         varchar(50)  DEFAULT NULL            COMMENT '卡片标题（空则用注册表默认标题）',
  unit          varchar(20)  DEFAULT NULL            COMMENT '单位（空则用注册表默认单位）',
  target_titles varchar(200) DEFAULT NULL            COMMENT '点击跳转的菜单标题（逗号分隔）',
  target_path   varchar(200) DEFAULT NULL            COMMENT '兜底路由路径',
  enabled       char(1)      NOT NULL DEFAULT '0'    COMMENT '状态（0启用 1停用）',
  remark        varchar(255) DEFAULT NULL            COMMENT '备注',
  create_time   datetime     DEFAULT NULL            COMMENT '创建时间',
  update_time   datetime     DEFAULT NULL            COMMENT '更新时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_role_metric (role_key, metric_key)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='首页岗位 KPI 配置';

-- 2. 补齐两个缺失岗位（综合办公室负责人 / 人力资源负责人）
INSERT INTO sys_role (role_name, role_key, role_sort, data_scope, menu_check_strictly, dept_check_strictly, status, del_flag, create_by, create_time, remark)
SELECT '综合办公室负责人', 'office_manager', 7, '1', 1, 1, '0', '0', 'admin', NOW(), '行政后勤、车辆、印章、安全事务负责人（首页岗位 KPI 已配置）'
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM sys_role WHERE role_key = 'office_manager');

INSERT INTO sys_role (role_name, role_key, role_sort, data_scope, menu_check_strictly, dept_check_strictly, status, del_flag, create_by, create_time, remark)
SELECT '人力资源负责人', 'hr_manager', 8, '1', 1, 1, '0', '0', 'admin', NOW(), '人事、考勤、合同、薪酬负责人（首页岗位 KPI 已配置）'
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM sys_role WHERE role_key = 'hr_manager');

