-- ============================================================
-- S. upgrade_20261118_oa_resource_flow.sql —— OA资源台账与流程联动(状态字典加占用值)
-- ============================================================
-- ============================================================
-- 综合办公：资源台账与流程联动升级
-- 1) 公车使用申请「指派车辆」「指派驾驶员」改为台账选择器
-- 2) 司机、印章状态字典增加“占用”值（车辆复用已有的“使用中”）
-- 执行日期：2026-11-18
-- ============================================================

-- ---------- 1. 公车使用申请表单字段 ----------
-- 指派车辆：文本 -> 车辆台账选择器（oaVehicle）
UPDATE flow_form
SET fields_json = REPLACE(
        fields_json,
        '"field":"assigned_vehicle","label":"指派车辆","form":"text","dtype":"text","length":100,"scale":2,"table":"main","order":20,"placeholder":"调度节点填写，车牌号"',
        '"field":"assigned_vehicle","label":"指派车辆","form":"browse","browseType":"oaVehicle","browseMultiple":false,"dtype":"text","length":200,"scale":2,"table":"main","order":20,"placeholder":"请选择车辆"'
    )
WHERE form_key = 'bus_use_apply';

-- 指派驾驶员：系统用户选择器 -> 司机台账选择器（oaDriver）
UPDATE flow_form
SET fields_json = REPLACE(
        fields_json,
        '"field":"assigned_driver","label":"指派驾驶员","form":"browse","browseType":"user","browseMultiple":false,"dtype":"text","length":1000,"scale":2,"table":"main","order":21,"placeholder":"调度节点填写"',
        '"field":"assigned_driver","label":"指派驾驶员","form":"browse","browseType":"oaDriver","browseMultiple":false,"dtype":"text","length":200,"scale":2,"table":"main","order":21,"placeholder":"请选择司机"'
    )
WHERE form_key = 'bus_use_apply';

-- ---------- 2. 状态字典 ----------
-- 司机：出车中（占用）
INSERT INTO sys_dict_data (dict_sort, dict_label, dict_value, dict_type, css_class, list_class, is_default, status, create_by, create_time)
SELECT 4, '出车中', '3', 'oa_driver_status', '', 'primary', 'N', '0', 'admin', sysdate()
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_data WHERE dict_type = 'oa_driver_status' AND dict_value = '3');

-- 印章：外带使用中（仅携出盖章占用）
INSERT INTO sys_dict_data (dict_sort, dict_label, dict_value, dict_type, css_class, list_class, is_default, status, create_by, create_time)
SELECT 4, '外带使用中', '3', 'oa_seal_status', '', 'primary', 'N', '0', 'admin', sysdate()
WHERE NOT EXISTS (SELECT 1 FROM sys_dict_data WHERE dict_type = 'oa_seal_status' AND dict_value = '3');


-- ============================================================
-- T. upgrade_20261118_seal_external_use.sql —— 印章外借字段
-- ============================================================
-- ============================================================
-- 综合办公：印章“外带使用中”改造
-- 1) 状态字典：使用中 -> 外带使用中（仅携出盖章占用）
-- 2) 历史数据纠正：现场盖章不应占用，恢复为正常
-- 执行日期：2026-11-18
-- ============================================================

UPDATE sys_dict_data
SET dict_label = '外带使用中'
WHERE dict_type = 'oa_seal_status' AND dict_value = '3';

-- 已将现场盖章流程关联的印章状态错误置为“使用中”的，恢复为正常
UPDATE biz_oa_seal s
JOIN flow_data_17 f ON f.process_instance_id = s.flow_instance_id
SET s.status = '0'
WHERE s.status = '3'
  AND (f.use_mode IS NULL OR f.use_mode <> '携出盖章');


-- ============================================================
-- U. upgrade_20261118_oa_attendance_flows.sql —— OA补卡/加班考勤流程
-- ============================================================
-- =============================================================
-- OA 考勤类审批流（出差申请、外出申请、打卡补卡）与考勤模块集成
-- 1. 流程配置（表单 flow_form、流程模型 act_re_model、部署）通过「流程管理」界面/API 配置，
--    参考脚本 tmp/build_oa_flows.js（标准库 ry-vue 已配置完成）
-- 2. 考勤联动代码：
--    - ruoyi-flowable: FlowArchiveHandler SPI / FlowArchiveDispatchListener（实例办结分发归档）
--                      FlowFormOptionsProvider SPI（表单动态选项，optionsSource）
--    - ruoyi-hr:       HrFlowArchiveService（出差单/外出单/补卡修正/请假单回写）
--                      HrShiftOptionsProvider（补卡班次选项来自 biz_hr_shift）
-- 3. 补卡班次选项直接引用考勤模块班次配置 biz_hr_shift，无需单独字典（本脚本无DDL/字典操作）
-- =============================================================


-- ============================================================
-- V. upgrade_20261119_seal_form_simplify.sql —— 用印表单精简
-- ============================================================
-- =============================================================
-- upgrade_20261119_seal_form_simplify.sql
-- 用印申请表单（flow_form form_id=17）简化：
--   1. 删除「用章类型」字段（seal_type），其与「用印印章」（seal_name，印章台账选择器）语义重复；
--   2. 「用印印章」移到原「用章类型」位置（申请日期同一行右侧）；
--   3. 原「实际盖章日期」字段横向加宽补齐底部行，表格边框保持完整。
-- 幂等：layout_json 中已无 seal_type 时自动跳过。
-- 历史数据保留：flow_data_17.seal_type 列及既有流程记录不动。
