-- AC. upgrade_20261123_wms_material_cost_price.sql —— 物料计价参考成本价+库存金额权限
-- ============================================================
-- ============================================================
-- 仓库管理：物料计价参考成本价 + 库存金额查看权限
--
-- 变更内容：
--   1) wms_material 新增 cost_price（计价参考成本价，不含税，2 位小数）
--      用途：仅作为财务入库计价在「入库明细单价缺失」时的兜底价。
--      不是采购价（采购价见 pms_supplier_catalog.unit_price），
--      也不是销售价（销售价见 mk_price_policy）。
--   2) 新增菜单权限点 wms:inventory:amount（库存金额查看）
--      金额属敏感数据，与 wms:inventory:list 分离；
--      OpenAPI / MCP 服务账号默认不授予，避免成本价对外泄露。
--
-- 执行库：按实际环境替换（开发库 ry-vue，其余环境同名库）
-- 执行日期：2026-11-23
-- 幂等性：字段存在性、权限存在性均先判断，可重复执行
-- 兼容性：需与新版本后端 jar 同时上线；旧 jar 不读该字段，可安全回滚（字段留空即可）
-- ============================================================


-- 强制 utf8mb4：Windows 下 mysql 客户端默认 gbk，会把中文注释写成乱码
SET NAMES utf8mb4;

-- ---------- 1. wms_material.cost_price ----------
SET @col_exists := (
    SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'wms_material'
      AND COLUMN_NAME = 'cost_price'
);

SET @ddl := IF(@col_exists = 0,
    'ALTER TABLE wms_material ADD COLUMN cost_price DECIMAL(18,2) NULL DEFAULT NULL COMMENT ''计价参考成本价（不含税，入库计价兜底，非采购价/销售价）'' AFTER is_batch_manage',
    'SELECT ''cost_price 已存在，跳过'' AS note');

PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------- 2. 库存金额查看权限点 ----------
-- 挂在「库存查询」菜单(2080)下，排序 4（避开既有 2082 query / 2083 export / 2123 remove）
SET @inv_menu_id := (SELECT menu_id FROM sys_menu WHERE perms = 'wms:inventory:list' LIMIT 1);

SET @perm_exists := (
    SELECT COUNT(*) FROM sys_menu WHERE perms = 'wms:inventory:amount'
);

INSERT INTO sys_menu (menu_name, parent_id, order_num, path, component, query, route_name, is_frame,
                      is_cache, menu_type, visible, status, perms, icon, create_by, create_time, remark)
SELECT '库存金额查看', @inv_menu_id, 4, '', '', '', '', 1, 0, 'F', '0', '0',
       'wms:inventory:amount', '#', 'admin', sysdate(),
       '金额为敏感数据，单独授权；不授予则库存列表不返回金额字段'
FROM DUAL
WHERE @perm_exists = 0 AND @inv_menu_id IS NOT NULL;

-- 授予超级管理员（role_id=1），其余角色按需在角色管理中勾选
SET @new_perm_id := (SELECT menu_id FROM sys_menu WHERE perms = 'wms:inventory:amount' LIMIT 1);

INSERT INTO sys_role_menu (role_id, menu_id)
SELECT 1, @new_perm_id FROM DUAL
WHERE @new_perm_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM sys_role_menu WHERE role_id = 1 AND menu_id = @new_perm_id
  );

-- ---------- 3. 校验 ----------
-- 字段是否建好
SELECT COLUMN_NAME, COLUMN_TYPE, IS_NULLABLE, COLUMN_COMMENT
FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA = DATABASE()
  AND TABLE_NAME = 'wms_material'
  AND COLUMN_NAME = 'cost_price';

-- 权限点是否建好
SELECT menu_id, menu_name, parent_id, perms, menu_type
FROM sys_menu
WHERE perms = 'wms:inventory:amount';

-- 尚未维护兜底价的物料数（应为全量，随维护逐步下降）
SELECT COUNT(*) AS total_material,
       SUM(CASE WHEN cost_price IS NULL OR cost_price = 0 THEN 1 ELSE 0 END) AS no_cost_price
FROM wms_material
WHERE del_flag = '0';


-- ============================================================
-- AD. upgrade_20261123_flow_data_leave_form.sql —— 补齐请假流程业务表
-- ============================================================
-- =============================================================
-- 补齐请假流程业务表：flow_data_leave_form
--
-- 背景（同步遗漏）：
--   upgrade_20261118_flow_config_data.sql 同步了请假申请表单的定义
--   （flow_form form_id=2，form_key=leave_form，table_name=flow_data_leave_form），
--   但同一批同步里只给报销/公车/出差/外出/补卡写了 CREATE TABLE，漏掉了请假流程
--   的建表语句。结果 flow_form.table_name 指向一张不存在的表。
--
--   流程台账配置页「字段」候选项的业务字段（source=main）来自：
--     FlowLedgerServiceImpl.selectLedgerFields(formId)
--   → 读取 information_schema.COLUMNS WHERE TABLE_NAME = form.tableName
--   → 表不存在时返回 0 列，页面只剩 8 个系统字段，业务表单字段全部缺失。
--
-- 影响：配置请假流程台账时选不到「请假类型/开始日期/结束日期/请假天数/请假事由」等业务字段。
--
-- 修复方式：
--   1. 建表（本脚本，幂等 CREATE TABLE IF NOT EXISTS）；
--   2. 若目标环境已有该表但缺列，走「流程管理 → 表单管理 → 数据表生成」
--      （POST /flowable/form/createTable/{formId}），后端 createOrPatchTable 会自动补列。
--
-- 列结构依据 flow_form.form_id=2 的 fields_json（15 个业务/系统字段）+ 流程运行所需的
-- 内部列（process_instance_id / create_by / create_time），与其余 flow_data_* 表保持一致。
-- =============================================================

CREATE TABLE IF NOT EXISTS `flow_data_leave_form` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL COMMENT '标题',
  `processNo` varchar(64) DEFAULT NULL COMMENT '流程编号',
  `urgency` varchar(20) DEFAULT NULL COMMENT '紧急程度',
  `signOpinion` varchar(4000) DEFAULT NULL COMMENT '签字意见',
  `printCount` int DEFAULT NULL COMMENT '打印次数',
  `procStatus` varchar(20) DEFAULT NULL COMMENT '流程状态',
  `sqr` varchar(1000) DEFAULT NULL COMMENT '申请人',
  `sqbm` varchar(1000) DEFAULT NULL COMMENT '申请部门',
  `sqrq` date DEFAULT NULL COMMENT '申请日期',
  `leave_type` varchar(40) DEFAULT NULL COMMENT '请假类型',
  `start_date` datetime DEFAULT NULL COMMENT '开始日期',
  `end_date` datetime DEFAULT NULL COMMENT '结束日期',
  `days` decimal(18,1) DEFAULT NULL COMMENT '请假天数',
  `reason` varchar(500) DEFAULT NULL COMMENT '请假事由',
  `xgfj` varchar(500) DEFAULT NULL COMMENT '相关附件',
  `process_instance_id` varchar(64) DEFAULT NULL COMMENT '流程实例ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_title` (`title`(191)),
  KEY `idx_urgency` (`urgency`),
  KEY `idx_process_no` (`processNo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='请假申请流程数据';

-- 校验：应返回 19 列（含 id），且存在 leave_type / start_date / end_date / days / reason / xgfj
-- SELECT COLUMN_NAME, COLUMN_COMMENT FROM information_schema.COLUMNS
--  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'flow_data_leave_form'
--  ORDER BY ORDINAL_POSITION;


-- ============================================================
-- AE. upgrade_20261123_integration_binding_to_sysuser.sql —— 集成绑定口径调整为sys_user
-- ============================================================
-- =============================================================
-- 集成模块绑定口径调整：外部平台用户绑定到平台组织用户（sys_user）
-- 版本: v1.0  日期: 2026-11-23
--
-- 背景：原人工绑定/自动匹配均以 HR 员工档案（biz_hr_employee）为绑定对象，
--       前端选人组件已统一改为组织用户（sys_user），导致绑定时报
--       「工号 xxx 未找到对应员工档案」。本次将绑定权威对象调整为 sys_user，
--       employee_no/employee_id 降级为考勤落库的派生信息（所选用户关联了
--       员工档案时回填，未关联留空，考勤同步按未映射跳过）。
--
-- 幂等：可重复执行。
-- =============================================================

-- 1. 新增 user_id 列（绑定权威对象：sys_user.user_id）
SET @col_exists := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME = 'integration_user_binding'
     AND COLUMN_NAME = 'user_id'
);
SET @ddl := IF(@col_exists = 0,
  'ALTER TABLE `integration_user_binding` ADD COLUMN `user_id` BIGINT DEFAULT NULL COMMENT ''平台组织用户ID(sys_user.user_id，绑定权威对象)'' AFTER `employee_id`',
  'SELECT ''user_id 已存在，跳过'' AS result');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 2. 存量数据迁移：按档案关联（biz_hr_employee.user_id）回填 user_id
--    仅迁移当前仍以 employee_id 绑定且 user_id 为空的行
UPDATE integration_user_binding b
JOIN biz_hr_employee e ON b.employee_id = e.employee_id AND e.user_id IS NOT NULL
SET b.user_id = e.user_id
WHERE b.user_id IS NULL AND b.employee_id IS NOT NULL;

-- 3. 唯一索引迁移：uk_connector_employee (connector_type, employee_id)
--    → uk_connector_user_id (connector_type, user_id)，与一一绑定新口径一致
SET @old_idx := (
  SELECT COUNT(*) FROM information_schema.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME = 'integration_user_binding'
     AND INDEX_NAME = 'uk_connector_employee'
);
SET @ddl := IF(@old_idx > 0,
  'ALTER TABLE `integration_user_binding` DROP INDEX `uk_connector_employee`',
  'SELECT ''uk_connector_employee 不存在，跳过删除'' AS result');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @new_idx := (
  SELECT COUNT(*) FROM information_schema.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME = 'integration_user_binding'
     AND INDEX_NAME = 'uk_connector_user_id'
);
SET @ddl := IF(@new_idx = 0,
  'ALTER TABLE `integration_user_binding` ADD UNIQUE KEY `uk_connector_user_id` (`connector_type`, `user_id`)',
  'SELECT ''uk_connector_user_id 已存在，跳过'' AS result');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 4. 自检：迁移后不应存在「同一用户被同一连接器多个外部账号绑定」的数据
SELECT connector_type, user_id, COUNT(*) AS cnt
FROM integration_user_binding
WHERE user_id IS NOT NULL
GROUP BY connector_type, user_id
HAVING COUNT(*) > 1;
-- 预期：0 行。若出现非 0 行，说明存量数据本身违反一一绑定，需人工核对解绑后再建索引。

-- 5. 复核：user_id 列与 uk_connector_user_id 索引均应存在
SHOW COLUMNS FROM `integration_user_binding` LIKE 'user_id';
SHOW INDEX FROM `integration_user_binding` WHERE Key_name = 'uk_connector_user_id';


-- ============================================================
-- AF. ai_nav_intent.sql —— AI导航意图建表+菜单字段与清洗(先于种子执行)
-- ============================================================
-- ============================================================
-- AI 菜单直达：完整落地方案（P1 导航框架 + P2 文档-菜单绑定）
-- 适用：RuoYi-Vue3 / MySQL 8
-- 幂等：可重复执行
-- ============================================================

-- ------------------------------------------------------------
-- 1. AI导航意图表（问题 → 系统菜单）
--    核心设计：只存 menu_id，不存 path
--    路径由服务端按登录人权限菜单树实时计算，菜单改名/改路径/改权限均无需维护本表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_nav_intent (
  intent_id    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  intent_key   VARCHAR(64)  NOT NULL                COMMENT '意图标识（LLM选择用，唯一）',
  menu_id      BIGINT       NOT NULL                COMMENT '目标菜单ID（sys_menu.menu_id），路径由服务端计算',
  module_code  VARCHAR(32)  NOT NULL                COMMENT '模块编码（wms/dms/qms/pms/mms/mk/hr/safety/bid/fin/flow/ai），两级路由用',
  title        VARCHAR(100) NOT NULL                COMMENT '展示名称，如 入库单管理',
  aliases      VARCHAR(500) DEFAULT ''              COMMENT '别名/同义词，英文逗号分隔（规则命中用，需按客户口语补）',
  examples     VARCHAR(500) DEFAULT ''              COMMENT '示例问句，英文逗号分隔（给LLM做语义参考）',
  nav_query    VARCHAR(300) DEFAULT ''              COMMENT '跳转附加参数JSON，如 {"status":"0"}；页面未适配时为null',
  doc_id       BIGINT       DEFAULT NULL            COMMENT '绑定的知识文档ID（P2 文档直连，优先于语义路由）',
  sort_no      INT          DEFAULT 0               COMMENT '排序权重，越大越优先',
  status       CHAR(1)      DEFAULT '0'             COMMENT '状态（0正常 1停用）',
  create_by    VARCHAR(64)  DEFAULT '',
  create_time  DATETIME     DEFAULT CURRENT_TIMESTAMP,
  update_by    VARCHAR(64)  DEFAULT '',
  update_time  DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (intent_id),
  UNIQUE KEY uk_intent_key (intent_key),
  KEY idx_module (module_code),
  KEY idx_menu (menu_id),
  KEY idx_doc (doc_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI导航意图表：用户问题 → 系统功能菜单';

-- ------------------------------------------------------------
-- 2. 知识文档关联功能入口（P2）
--    上传手册时选好归属页面，问答命中该文档即可确定性给出入口，不依赖模型猜测
-- ------------------------------------------------------------
-- MySQL 8.0 不支持 ADD COLUMN IF NOT EXISTS，用存储过程保证幂等
DROP PROCEDURE IF EXISTS add_nav_menu_id_to_knowledge_doc;
DELIMITER $$
CREATE PROCEDURE add_nav_menu_id_to_knowledge_doc()
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'ai_knowledge_doc'
      AND COLUMN_NAME = 'nav_menu_id'
  ) THEN
    ALTER TABLE ai_knowledge_doc
      ADD COLUMN nav_menu_id BIGINT DEFAULT NULL
      COMMENT '关联功能入口菜单ID（sys_menu.menu_id），问答命中该文档时直接给出入口';
  END IF;
END$$
DELIMITER ;
CALL add_nav_menu_id_to_knowledge_doc();
DROP PROCEDURE IF EXISTS add_nav_menu_id_to_knowledge_doc;

-- ------------------------------------------------------------
-- 3. 配置开关（沿用 sys_config 体系）
-- ------------------------------------------------------------
INSERT INTO sys_config (config_name, config_key, config_value, config_type, create_by, create_time, remark)
SELECT 'AI导航开关', 'ai.nav.enabled', 'true', 'Y', 'admin', NOW(),
       'AI问答后是否在答案下方显示可点击的系统功能入口'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM sys_config WHERE config_key = 'ai.nav.enabled');

